1	'use client';
2	
3	import {
4	    Box,
5	    Button,
6	    Group,
7	    Modal,
8	    Text,
9	    TextInput,
10	    Tooltip,
11	} from '@mantine/core';
12	import {
13	    notifications,
14	} from '@mantine/notifications';
15	import {
16	    Link,
17	    RichTextEditor,
18	} from '@mantine/tiptap';
19	import { IconAlertTriangle, IconCheck, IconUser } from '@tabler/icons-react';
20	import Highlight from '@tiptap/extension-highlight';
21	import Placeholder from '@tiptap/extension-placeholder';
22	import TextAlign from '@tiptap/extension-text-align';
23	import Underline from '@tiptap/extension-underline';
24	import { useEditor } from '@tiptap/react';
25	import StarterKit from '@tiptap/starter-kit';
26	import { useState } from 'react';
27	
28	import { config } from '@/lib/config';
29	import { normalizeEmail } from '@/lib/email/normalizeEmail';
30	import { toPublicMessage } from '@/lib/errors';
31	import { captureUnexpectedError } from '@/lib/observability/sentry';
32	import { PlayerDataEmailDisplayType } from '@/types';
33	import type { SendEmailProxy } from '@/types/actions/SendEmail';
34	
35	import classes from './SendEmailForm.module.css';
36	
37	export interface Props {
38	    opened: boolean;
39	    onClose: () => void;
40	    players: PlayerDataEmailDisplayType[];
41	    onSendEmail: SendEmailProxy;
42	    withinPortal?: boolean;
43	    withOverlay?: boolean;
44	}
45	
46	export const SendEmailForm = ({
47	    opened,
48	    onClose,
49	    players,
50	    onSendEmail,
51	    withinPortal,
52	    withOverlay,
53	}: Props) => {
54	    const [subject, setSubject] = useState('');
55	    const names = players.map(({ name }) => name).join(', ');
56	    const emails = Array.from(new Set(players.flatMap((player) => {
57	        const verifiedExtraEmails = player.extraEmails.filter((playerEmail) => playerEmail.verified);
58	        const preferredExtraEmails = verifiedExtraEmails.length > 0 ? verifiedExtraEmails : player.extraEmails;
59	        return [player.accountEmail, ...preferredExtraEmails.map((playerEmail) => playerEmail.email)];
60	    }).map(normalizeEmail).filter((email) => email.length > 0))).join(',');
61	
62	    const editor = useEditor({
63	        extensions: [
64	            Highlight,
65	            Link,
66	            Placeholder.configure({ placeholder: 'Message text' }),
67	            StarterKit,
68	            TextAlign.configure({ types: ['heading', 'paragraph'] }),
69	            Underline,
70	        ],
71	        content: '',
72	        immediatelyRender: false,
73	    });
74	
75	    if (!editor) return null;
76	
77	    const handleSubmit = async () => {
78	        const id = notifications.show({
79	            loading: true,
80	            title: 'Sending email',
81	            message: 'Sending email...',
82	            autoClose: false,
83	            withCloseButton: false,
84	        });
85	
86	        try {
87	            await onSendEmail({
88	                to: emails,
89	                subject,
90	                html: editor.getHTML(),
91	            });
92	
93	            onClose();
94	            notifications.update({
95	                id,
96	                color: 'teal',
97	                title: 'Email sent',
98	                message: 'Email sent successfully',
99	                icon: <IconCheck size={config.notificationIconSize} />,
100	                loading: false,
101	                autoClose: config.notificationAutoClose,
102	            });
103	        } catch (err) {
104	            captureUnexpectedError(err, {
105	                layer: 'client',
106	                component: 'SendEmailForm',
107	                action: 'sendEmail',
108	                route: '/footy/admin/players',
109	                extra: {
110	                    recipientCount: players.length,
111	                },
112	            });
113	            notifications.update({
114	                id,
115	                color: 'red',
116	                title: 'Error',
117	                message: toPublicMessage(err, 'Failed to send email.'),
118	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
119	                loading: false,
120	                autoClose: config.notificationAutoClose,
121	            });
122	        }
123	    };
124	
125	    return (
126	        <Modal
127	            opened={opened}
128	            onClose={onClose}
129	            title="Send Mail to Players"
130	            size="lg"
131	            withinPortal={withinPortal}
132	            withOverlay={withOverlay}
133	        >
134	            <Tooltip label={names} multiline>
135	                <Text size="sm" mt="sm" lineClamp={1}>
136	                    <IconUser size={16} className={classes.users} />
137	                    <strong>To:</strong> {names}
138	                </Text>
139	            </Tooltip>
140	            <form onSubmit={(e) => { e.preventDefault(); void handleSubmit(); }}>
141	                <TextInput
142	                    label="Subject"
143	                    value={subject}
144	                    onChange={(event) => setSubject(event.currentTarget.value)}
145	                    required
146	                    mt="md"
147	                />
148	
149	                <RichTextEditor editor={editor} mt="md">
150	                    <RichTextEditor.Toolbar sticky stickyOffset={60}>
151	                        <RichTextEditor.ControlsGroup>
152	                            <RichTextEditor.Bold />
153	                            <RichTextEditor.Italic />
154	                            <RichTextEditor.Underline />
155	                            <RichTextEditor.Strikethrough />
156	                            <RichTextEditor.ClearFormatting />
157	                            <RichTextEditor.Highlight />
158	                            <RichTextEditor.Code />
159	                        </RichTextEditor.ControlsGroup>
160	
161	                        <RichTextEditor.ControlsGroup>
162	                            <RichTextEditor.H1 />
163	                            <RichTextEditor.H2 />
164	                            <RichTextEditor.H3 />
165	                            <RichTextEditor.H4 />
166	                        </RichTextEditor.ControlsGroup>
167	
168	                        <RichTextEditor.ControlsGroup>
169	                            <RichTextEditor.Blockquote />
170	                            <RichTextEditor.Hr />
171	                            <RichTextEditor.BulletList />
172	                            <RichTextEditor.OrderedList />
173	                        </RichTextEditor.ControlsGroup>
174	
175	                        <RichTextEditor.ControlsGroup>
176	                            <RichTextEditor.Link />
177	                            <RichTextEditor.Unlink />
178	                        </RichTextEditor.ControlsGroup>
179	
180	                        <RichTextEditor.ControlsGroup>
181	                            <RichTextEditor.AlignLeft />
182	                            <RichTextEditor.AlignCenter />
183	                            <RichTextEditor.AlignJustify />
184	                            <RichTextEditor.AlignRight />
185	                        </RichTextEditor.ControlsGroup>
186	                    </RichTextEditor.Toolbar>
187	
188	                    <RichTextEditor.Content />
189	                </RichTextEditor>
190	
191	                <Group justify="flex-end" mt="md">
192	                    <Tooltip label="No valid email addresses for the selected players" disabled={!!emails}>
193	                        <Box component="span">
194	                            <Button type="submit" disabled={!emails}>Send Mail</Button>
195	                        </Box>
196	                    </Tooltip>
197	                </Group>
198	            </form>
199	        </Modal>
200	    );
201	};
