1	'use client';
2	
3	import {
4	    Button,
5	    Checkbox,
6	    Container,
7	    Divider,
8	    Group,
9	    Paper,
10	    Stack,
11	    Table,
12	    Text,
13	    TextInput,
14	    Title,
15	    UnstyledButton,
16	} from '@mantine/core';
17	import {
18	    notifications,
19	} from '@mantine/notifications';
20	import { IconAlertTriangle, IconCheck, IconChevronDown, IconChevronUp, IconSelector } from '@tabler/icons-react';
21	import { useRouter } from 'next/navigation';
22	import { GameDayType } from 'prisma/zod/schemas/models/GameDay.schema';
23	import { useMemo, useState } from 'react';
24	
25	import { config } from '@/lib/config';
26	import { formatDate } from '@/lib/dates';
27	import type { SetGameEnabledProxy } from '@/types/actions/SetGameEnabled';
28	import type { SubmitPickerProxy } from '@/types/actions/SubmitPicker';
29	import type { PickerPlayerType } from '@/types/PickerPlayerType';
30	
31	// Breakpoint at which the cancel/reinstate controls switch from a stacked
32	// mobile layout to a single-line row; kept as one constant so every field agrees.
33	const actionsBreakpoint = 'sm';
34	
35	interface PickerFormProps {
36	    gameDay: GameDayType;
37	    players: PickerPlayerType[];
38	    submitPicker: SubmitPickerProxy;
39	    setGameEnabled: SetGameEnabledProxy;
40	}
41	
42	export const PickerForm = ({
43	    gameDay,
44	    players,
45	    submitPicker,
46	    setGameEnabled,
47	}: PickerFormProps) => {
48	    const router = useRouter();
49	    const eligiblePlayers = useMemo(
50	        () => players.filter((player) => player.response === 'Yes'),
51	        [players],
52	    );
53	    const [sortKey, setSortKey] = useState<SortKey>('responseTime');
54	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
55	    const [selectedIds, setSelectedIds] = useState<number[]>(() => buildDefaultSelection(eligiblePlayers));
56	    const [isSubmitting, setIsSubmitting] = useState(false);
57	    const [reason, setReason] = useState('');
58	    const [isSettingEnabled, setIsSettingEnabled] = useState(false);
59	
60	    const sortedPlayers = useMemo(() => {
61	        const data = [...eligiblePlayers];
62	        data.sort((a, b) => {
63	            switch (sortKey) {
64	                case 'name':
65	                    return compareNullableString(a.player.name, b.player.name, sortDirection);
66	                case 'responseTime':
67	                    return compareNullableNumber(a.responseInterval, b.responseInterval, sortDirection);
68	                case 'gamesPlayed':
69	                    return compareNullableNumber(a.gamesPlayed, b.gamesPlayed, sortDirection);
70	                /* v8 ignore next 2 -- SortKey is a union type; default is unreachable */
71	                default:
72	                    return 0;
73	            }
74	        });
75	        return data;
76	    }, [eligiblePlayers, sortKey, sortDirection]);
77	
78	    const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);
79	    const filteredSelectedCount = useMemo(() => (
80	        eligiblePlayers.reduce((acc, row) => (selectedIdSet.has(row.playerId) ? acc + 1 : acc), 0)
81	    ), [eligiblePlayers, selectedIdSet]);
82	
83	    const allSelected = eligiblePlayers.length > 0 && filteredSelectedCount === eligiblePlayers.length;
84	    const someSelected = filteredSelectedCount > 0 && !allSelected;
85	    const hasSelection = filteredSelectedCount > 0;
86	
87	    const selectedPlayers = useMemo(() => (
88	        eligiblePlayers.filter((player) => selectedIdSet.has(player.playerId))
89	    ), [eligiblePlayers, selectedIdSet]);
90	
91	    const toggleSelectAll = (checked: boolean) => {
92	        if (checked) {
93	            setSelectedIds((prev) => Array.from(new Set([
94	                ...prev,
95	                ...eligiblePlayers.map((player) => player.playerId),
96	            ])));
97	            return;
98	        }
99	
100	        const eligibleIdSet = new Set(eligiblePlayers.map((player) => player.playerId));
101	        setSelectedIds((prev) => prev.filter((id) => !eligibleIdSet.has(id)));
102	    };
103	
104	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
105	        setSelectedIds((prev) => {
106	            if (checked) {
107	                /* v8 ignore next -- defensive guard against duplicate adds; normal checkbox behaviour never fires checked=true when already selected */
108	                return prev.includes(playerId) ? prev : [...prev, playerId];
109	            }
110	            return prev.filter((id) => id !== playerId);
111	        });
112	    };
113	
114	    const handleSort = (key: SortKey) => {
115	        if (key === sortKey) {
116	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
117	            return;
118	        }
119	        setSortKey(key);
120	        setSortDirection('asc');
121	    };
122	
123	    const getSortIcon = (key: SortKey) => {
124	        if (key !== sortKey) return <IconSelector size={14} />;
125	        return sortDirection === 'asc' ? <IconChevronUp size={14} /> : <IconChevronDown size={14} />;
126	    };
127	
128	    const renderSortHeader = (label: string, key: SortKey) => (
129	        <UnstyledButton
130	            type="button"
131	            onClick={() => handleSort(key)}
132	            aria-label={`Sort by ${label}`}
133	        >
134	            <Group gap={6} wrap="nowrap">
135	                <Text span>{label}</Text>
136	                {getSortIcon(key)}
137	            </Group>
138	        </UnstyledButton>
139	    );
140	
141	    const handleSubmit = async () => {
142	        /* v8 ignore next 7 -- Pick sides button is disabled when !hasSelection; guard is a defensive backstop */
143	        if (!hasSelection) {
144	            notifications.show({
145	                color: 'yellow',
146	                title: 'No players selected',
147	                message: 'Select at least one player before submitting.',
148	            });
149	            return;
150	        }
151	
152	        const notificationId = 'picker-submit';
153	        notifications.show({
154	            id: notificationId,
155	            loading: true,
156	            title: 'Submitting picker',
157	            message: 'Submitting selected players...',
158	            autoClose: false,
159	            withCloseButton: false,
160	        });
161	
162	        setIsSubmitting(true);
163	        try {
164	            await submitPicker(
165	                selectedPlayers.map((player) => ({
166	                    playerId: player.playerId,
167	                })),
168	            );
169	            notifications.update({
170	                id: notificationId,
171	                color: 'teal',
172	                title: 'Selection submitted',
173	                message: `${selectedPlayers.length} players submitted.`,
174	                icon: <IconCheck size={config.notificationIconSize} />,
175	                loading: false,
176	                autoClose: config.notificationAutoClose,
177	            });
178	
179	            router.push(`/footy/game/${gameDay.id}`);
180	        } catch (err) {
181	            const errorMessage = err instanceof Error ? err.message : 'Failed to submit selection';
182	            notifications.update({
183	                id: notificationId,
184	                color: 'red',
185	                title: 'Error',
186	                message: errorMessage,
187	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
188	                loading: false,
189	                autoClose: false,
190	                withCloseButton: true,
191	            });
192	        } finally {
193	            setIsSubmitting(false);
194	        }
195	    };
196	
197	    const handleSetGameEnabled = async () => {
198	        const notificationId = 'set-enabled';
199	        notifications.show({
200	            id: notificationId,
201	            loading: true,
202	            title: 'Updating game status',
203	            message: 'Updating game status...',
204	            autoClose: false,
205	            withCloseButton: false,
206	        });
207	
208	        setIsSettingEnabled(true);
209	        try {
210	            await setGameEnabled(
211	                {
212	                    gameDayId: gameDay.id,
213	                    game: !gameDay.game,
214	                    reason: reason,
215	                },
216	            );
217	            notifications.update({
218	                id: notificationId,
219	                color: 'teal',
220	                title: gameDay.game ? 'Game cancelled' : 'Game reinstated',
221	                message: gameDay.game ? 'The game has been marked as cancelled.' : 'The game has been reinstated.',
222	                icon: <IconCheck size={config.notificationIconSize} />,
223	                loading: false,
224	                autoClose: config.notificationAutoClose,
225	            });
226	        } catch (err) {
227	            const errorMessage = err instanceof Error ? err.message : 'Failed to set game status';
228	            notifications.update({
229	                id: notificationId,
230	                color: 'red',
231	                title: 'Error',
232	                message: errorMessage,
233	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
234	                loading: false,
235	                autoClose: false,
236	                withCloseButton: true,
237	            });
238	        } finally {
239	            setIsSettingEnabled(false);
240	        }
241	    };
242	
243	    const rows = sortedPlayers.map((player) => {
244	        const playerName = getPlayerName(player);
245	
246	        return (
247	            <Table.Tr key={player.playerId}>
248	                <Table.Td w="2.5rem">
249	                    <Checkbox
250	                        checked={selectedIdSet.has(player.playerId)}
251	                        onChange={(event) => toggleSelectPlayer(player.playerId, event.currentTarget.checked)}
252	                        aria-label={`Select ${playerName}`}
253	                    />
254	                </Table.Td>
255	                <Table.Td>{playerName}</Table.Td>
256	                <Table.Td>{formatResponseInterval(player.responseInterval ?? null)}</Table.Td>
257	                <Table.Td>{player.gamesPlayed}</Table.Td>
258	            </Table.Tr>
259	        );
260	    });
261	
262	    const picker = (
263	        <>
264	            <Group justify="space-between" align="center" wrap="wrap">
265	                <Text fw={700}>Players selected ({filteredSelectedCount})</Text>
266	                <Button
267	                    type="button"
268	                    onClick={handleSubmit}
269	                    disabled={!hasSelection || isSettingEnabled}
270	                    loading={isSubmitting}
271	                    w={{ base: '100%', [actionsBreakpoint]: 150 }}
272	                >
273	                    Pick sides
274	                </Button>
275	            </Group>
276	            <Table.ScrollContainer minWidth={480} scrollAreaProps={{ type: 'auto' }}>
277	                <Table
278	                    striped
279	                    highlightOnHover
280	                    withTableBorder
281	                    withColumnBorders
282	                    w="100%"
283	                    layout="fixed"
284	                >
285	                    <Table.Thead>
286	                        <Table.Tr>
287	                            <Table.Th w="2.5rem">
288	                                <Checkbox
289	                                    checked={allSelected}
290	                                    indeterminate={someSelected}
291	                                    onChange={(event) => toggleSelectAll(event.currentTarget.checked)}
292	                                    aria-label="Select all players"
293	                                />
294	                            </Table.Th>
295	                            <Table.Th aria-sort={sortKey === 'name' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
296	                                {renderSortHeader('Player', 'name')}
297	                            </Table.Th>
298	                            <Table.Th aria-sort={sortKey === 'responseTime' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
299	                                {renderSortHeader('Response time', 'responseTime')}
300	                            </Table.Th>
301	                            <Table.Th aria-sort={sortKey === 'gamesPlayed' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
302	                                {renderSortHeader('Total games played', 'gamesPlayed')}
303	                            </Table.Th>
304	                        </Table.Tr>
305	                    </Table.Thead>
306	                    <Table.Tbody>{rows}</Table.Tbody>
307	                </Table>
308	            </Table.ScrollContainer>
309	            <Divider
310	                label="or"
311	                labelPosition="center"
312	            />
313	        </>
314	    );
315	
316	    // TODO: New game date component?
317	    return (
318	        <Container fluid>
319	            <Paper w="100%" p="xl">
320	                <Stack gap="md">
321	                    <Stack align="flex-start" gap="xs">
322	                        <Title order={2}>Picker</Title>
323	                        <Text c="dimmed">Game {gameDay.id}: {formatDate(gameDay.date)}</Text>
324	                    </Stack>
325	                    {gameDay.game ? picker : null}
326	                    <Group
327	                        justify="space-between"
328	                        align="center"
329	                        wrap="wrap"
330	                    >
331	                        <TextInput
332	                            aria-label={gameDay.game ? "Cancellation reason" : "Reinstatement reason"}
333	                            placeholder={gameDay.game ? "not enough players" : ""}
334	                            value={reason}
335	                            onChange={(event) => setReason(event.currentTarget.value)}
336	                            disabled={isSubmitting || isSettingEnabled}
337	                            flex={1}
338	                        />
339	                        <Button
340	                            type="button"
341	                            color={gameDay.game ? "red" : "green"}
342	                            onClick={handleSetGameEnabled}
343	                            loading={isSettingEnabled}
344	                            disabled={isSubmitting || isSettingEnabled}
345	                            w={{ base: '100%', [actionsBreakpoint]: 150 }}
346	                        >
347	                            {gameDay.game ? 'Cancel game' : 'Reinstate game'}
348	                        </Button>
349	                    </Group>
350	                </Stack>
351	            </Paper>
352	        </Container>
353	    );
354	};
355	
356	type SortKey = 'name' | 'responseTime' | 'gamesPlayed';
357	type SortDirection = 'asc' | 'desc';
358	
359	const compareNullableNumber = (
360	    a: number | null | undefined,
361	    b: number | null | undefined,
362	    direction: SortDirection,
363	) => {
364	    if (a == null && b == null) return 0;
365	    if (a == null) return 1;
366	    if (b == null) return -1;
367	    return direction === 'asc' ? a - b : b - a;
368	};
369	
370	const compareNullableString = (
371	    a: string | null | undefined,
372	    b: string | null | undefined,
373	    direction: SortDirection,
374	) => {
375	    if (a == null && b == null) return 0;
376	    if (a == null) return 1;
377	    if (b == null) return -1;
378	    const result = a.localeCompare(b);
379	    return direction === 'asc' ? result : -result;
380	};
381	
382	const formatResponseInterval = (seconds: number | null | undefined) => {
383	    if (seconds == null) return '-';
384	    if (seconds < 60) return `${seconds}s`;
385	
386	    const minutes = Math.floor(seconds / 60);
387	    if (minutes < 60) return `${minutes}m`;
388	
389	    const hours = Math.floor(minutes / 60);
390	    const remainingMinutes = minutes % 60;
391	    if (hours < 24) {
392	        return remainingMinutes ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
393	    }
394	
395	    const days = Math.floor(hours / 24);
396	    const remainingHours = hours % 24;
397	    return remainingHours ? `${days}d ${remainingHours}h` : `${days}d`;
398	};
399	
400	const getPlayerName = (row: PickerPlayerType) => row.player.name ?? `Player ${row.playerId}`;
401	
402	const buildDefaultSelection = (rows: PickerPlayerType[], maxSelected = 12) => {
403	    if (!rows.length) return [];
404	    const sorted = [...rows].sort((a, b) => {
405	        const responseCompare = compareNullableNumber(a.responseInterval, b.responseInterval, 'asc');
406	        if (responseCompare !== 0) return responseCompare;
407	        const nameCompare = compareNullableString(a.player.name, b.player.name, 'asc');
408	        if (nameCompare !== 0) return nameCompare;
409	        return a.playerId - b.playerId;
410	    });
411	    return sorted.slice(0, maxSelected).map((row) => row.playerId);
412	};
