17	} from '@mantine/core';
18	import {
19	    notifications,
20	} from '@mantine/notifications';
21	import { IconAlertTriangle, IconCheck, IconChevronDown, IconChevronUp, IconSelector } from '@tabler/icons-react';
22	import { useRouter } from 'next/navigation';
23	import { useMemo, useState } from 'react';
24	
25	import { config } from '@/lib/config';
26	import type { SetDrinkersInput, SetDrinkersProxy } from '@/types/actions/SetDrinkers';
27	import type { OutcomePlayerType } from '@/types/OutcomePlayerType';
28	
29	interface DrinkersFormProps {
30	    gameId: number;
31	    gameDate: string;
32	    players: OutcomePlayerType[];
33	    setDrinkers: SetDrinkersProxy;
34	}
35	
36	export const DrinkersForm = ({
37	    gameId,
38	    gameDate,
39	    players,
40	    setDrinkers,
41	}: DrinkersFormProps) => {
42	    const router = useRouter();
43	    const [rows, setRows] = useState<OutcomePlayerType[]>(players);
44	    const [selectedIds, setSelectedIds] = useState<number[]>(() => toSelectedIds(players));
45	    const [savedSelectedIds, setSavedSelectedIds] = useState<number[]>(() => toSelectedIds(players));
46	    const [filter, setFilter] = useState('');
47	    const [sortKey, setSortKey] = useState<SortKey>('team');
48	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
49	    const [isSaving, setIsSaving] = useState(false);
50	    const [prevPlayers, setPrevPlayers] = useState(players);
51	
52	    if (prevPlayers !== players) {
