74	                    return compareNullableString(a.player.name, b.player.name, sortDirection);
75	                case 'team':
76	                    return compareNullableString(a.team, b.team, sortDirection);
77	                case 'response':
78	                    return compareNullableString(a.response, b.response, sortDirection);
79	                /* v8 ignore next 2 -- SortKey is a union type; default is unreachable */
80	                default:
81	                    return 0;
82	            }
83	        });
84	        return data;
85	    }, [filteredRows, sortKey, sortDirection]);
