87	    const allVisibleSelected =
88	        visibleRows.length > 0 &&
89	        visibleRows.every((row) => selectedIdSet.has(row.playerId));
90	
91	    const someVisibleSelected =
92	        visibleRows.some((row) => selectedIdSet.has(row.playerId)) && !allVisibleSelected;
93	
94	    const hasChanges = !isSameSelection(selectedIds, savedSelectedIds);
95	
96	    const togglePlayer = (playerId: number, checked: boolean) => {
97	        setSelectedIds((current) => {
98	            if (checked) {
99	                /* v8 ignore next -- defensive guard against duplicate adds; normal checkbox behaviour never fires checked=true when already selected */
