295	                                            <Table.Th w="6rem" aria-sort={sortKey === 'team' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
296	                                                {renderSortHeader('Team', 'team')}
297	                                            </Table.Th>
298	                                            <Table.Th w="8rem" aria-sort={sortKey === 'response' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
299	                                                {renderSortHeader('Response', 'response')}
300	                                            </Table.Th>
301	                                        </Table.Tr>
302	                                    </Table.Thead>
303	                                    <Table.Tbody>{renderedRows}</Table.Tbody>
304	                                </Table>
305	                            </Table.ScrollContainer>
306	                        </>
307	                    ) : (
