309	                    )}
310	                </Stack>
311	            </Paper>
312	        </Container>
313	    );
314	};
315	
316	type SortKey = 'name' | 'team' | 'response';
317	type SortDirection = 'asc' | 'desc';
318	
319	const compareNullableString = (
320	    a: string | null | undefined,
321	    b: string | null | undefined,
322	    direction: SortDirection,
323	) => {
324	    if (a == null && b == null) return 0;
325	    if (a == null) return 1;
326	    if (b == null) return -1;
327	    const result = a.localeCompare(b);
328	    return direction === 'asc' ? result : -result;
329	};
330	
331	const normaliseName = (row: OutcomePlayerType) => row.player.name ?? `Player ${row.playerId}`;
332	
333	const toSelectedIds = (rows: OutcomePlayerType[]) => rows
334	    .filter((row) => (row.pub ?? 0) > 0)
335	    .map((row) => row.playerId);
336	
337	const isSameSelection = (left: number[], right: number[]) => {
338	    if (left.length !== right.length) return false;
339	    const rightSet = new Set(right);
340	    return left.every((id) => rightSet.has(id));
341	};
