interface SampleRateOptions {
    /**
     * Environment variable to read, for example `SENTRY_TRACES_SAMPLE_RATE`.
     */
    envVarName: string;
    /**
     * Default sample rate used when `NODE_ENV === 'production'` and no valid
     * environment override is provided.
