    try {
        const url = new URL(rawUrl, 'http://localhost');
        for (const [key] of url.searchParams.entries()) {
            if (isSensitiveKey(key)) {
                url.searchParams.set(key, REDACTED_VALUE);
            }
        }

        if (rawUrl.startsWith('/')) {
